SELECT seq, ts, event_type AS eventType, data AS payload
FROM jade_events
WHERE run_id = #{runId} AND seq < #{before}
ORDER BY seq DESC
LIMIT #{limit}

SELECT seq, ts, event_type AS eventType, compact_data AS payload
FROM jade_events
WHERE run_id = #{runId} AND seq < #{before}
ORDER BY seq DESC
LIMIT #{limit}

SELECT seq, ts, event_type AS eventType, data AS payload
FROM jade_events
WHERE run_id = #{runId} AND seq = #{seq}
